let _lang = 'en';
function t(key, vars) {
  let s = (T[_lang] && T[_lang][key]) || T.en[key] || key;
  if (vars) Object.keys(vars).forEach(k => { s = s.replace(new RegExp('\\{' + k + '\\}', 'g'), vars[k]); });
  return s;
}
function setLang(code) {
  if (!T[code]) code = 'en';
  _lang = code;
  document.documentElement.lang = code;
  document.documentElement.dir = 'ltr';
  try { localStorage.setItem('hwc.lang', code); } catch (e) {}
  document.querySelectorAll('[data-i18n]').forEach(el => { el.textContent = t(el.getAttribute('data-i18n')); });
  const b = document.getElementById('btnLang'); if (b) b.textContent = code.toUpperCase();
}
function getLang() { return _lang; }
function initLang() {
  let code = null;
  try { code = localStorage.getItem('hwc.lang'); } catch (e) {}
  if (!code) {
    const nav = (navigator.language || 'en').slice(0, 2);
    code = T[nav] ? nav : null;
  }
  _lang = code || null; // null => first-entry language chooser
  if (_lang) setLang(_lang);
}
